<?php require __DIR__.'/inc/page_helpers.php';if(page_post()){check_csrf();$n=trim((string)($_POST['username']??''));$p=(string)($_POST['password']??'');if(!preg_match('/^[A-Za-z0-9_]{3,20}$/',$n)||strlen($p)<8||$p!==(string)($_POST['confirm']??'')){notice('Invalid username or passwords do not match.','error');go('/Register.php');}try{$q=$db->prepare('INSERT INTO users(username,password_hash,tickets) VALUES(?,?,1000)');$q->execute([$n,password_hash($p,PASSWORD_DEFAULT)]);session_regenerate_id(true);$_SESSION['user_id']=(int)$db->lastInsertId();record_currency($db,(int)$_SESSION['user_id'],'tickets',1000,'Welcome bonus');notice('Account created with 1,000 Tickets.');go('/');}catch(PDOException $e){if($e->getCode()==='23000'){notice('Username already exists.','error');go('/Register.php');}throw $e;}}page_start('Register');?><section class="Panel narrow"><h1>Create Account</h1><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Character Name<input name="username" maxlength="20" required></label><label>Password<input type="password" name="password" minlength="8" required></label><label>Confirm Password<input type="password" name="confirm" minlength="8" required></label><button class="Button">Register</button></form></section><?php page_end();